package com.offex7.streamhub

import android.graphics.BitmapFactory

import android.util.Base64

import androidx.compose.ui.graphics.ImageBitmap

import androidx.compose.ui.graphics.asImageBitmap


object RadioLogoAssets {

    private val encoded: Map<String, String> = mapOf(
        "CHILL HOUSE" to "",
        "CHOCOLATE" to "",
        "COMEDY CLUB" to "",
        "DATASET [AI]" to "",
        "METALCORE" to "",
        "PIRATE STATION" to "",
        "PSY TRANCE" to "",
        "RECORD" to "",
        "RELAX" to "",
        "ULTRA" to "",
        "VOCAL DRUM" to "",
        "АВТОРАДИО" to "",
        "ГАМАЮН" to "",
        "ЕВРОПА ПЛЮС" to "",
        "КАЛЬЯН РЭП" to "",
        "НАШЕ РАДИО" to "",
        "РЕТРО FM" to "",
        "ХИТ FM" to "",
        "ЭНЕРДЖИ" to "",
        "ЮГ МОЛОДОЙ" to ""
    )

    private val cache = HashMap<String, ImageBitmap>()

    fun image(name: String): ImageBitmap? {

        val key = name.trim().uppercase(java.util.Locale.ROOT)

        cache[key]?.let { return it }

        val bytes = encoded[key]?.let { runCatching { Base64.decode(it, Base64.DEFAULT) }.getOrNull() } ?: return null

        val bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap() ?: return null

        cache[key] = bitmap

        return bitmap

    }

}
